html:
{% set rows = doc.pricing_list or [] %}
{% set total_cost = rows | sum(attribute='ammount') %}
{% set total_sell = rows | sum(attribute='selling_ammount') %}

<style>
  body { font-family: Arial, sans-serif; font-size: 12px; color: #222; }
  .cs-header { display: flex; justify-content: space-between; align-items: flex-start;
               border-bottom: 2px solid #1a3a5c; padding-bottom: 10px; margin-bottom: 14px; }
  .cs-title { font-size: 20px; font-weight: 700; color: #1a3a5c; }
  .cs-meta { font-size: 11px; color: #555; margin-top: 4px; }
  .cs-info-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 6px 24px;
                  margin-bottom: 16px; font-size: 11.5px; }
  .cs-info-grid .lbl { color: #888; font-weight: 600; text-transform: uppercase;
                       font-size: 10px; letter-spacing: .04em; }
  .cs-info-grid .val { font-weight: 600; color: #1a3a5c; }
  table.pricing { width: 100%; border-collapse: collapse; margin-bottom: 12px; font-size: 11.5px; }
  table.pricing thead tr { background: #1a3a5c; color: #fff; }
  table.pricing thead th { padding: 6px 8px; text-align: left; font-size: 10.5px;
                           font-weight: 600; letter-spacing: .03em; }
  table.pricing thead th.r { text-align: right; }
  table.pricing tbody tr { border-bottom: 1px solid #e5e7eb; }
  table.pricing tbody tr:nth-child(even) { background: #f8fafc; }
  table.pricing tbody td { padding: 6px 8px; }
  table.pricing tbody td.r { text-align: right; font-family: monospace; }
  table.pricing tfoot tr { background: #1a3a5c; color: #fff; font-weight: 700; }
  table.pricing tfoot td { padding: 7px 8px; }
  table.pricing tfoot td.r { text-align: right; font-family: monospace; }
  .cs-footer { margin-top: 18px; font-size: 10px; color: #888;
               border-top: 1px solid #e5e7eb; padding-top: 8px; text-align: center; }
  .badge { display: inline-block; padding: 1px 8px; border-radius: 10px;
           font-size: 10px; font-weight: 700; }
  .badge-blue  { background: #dbeafe; color: #1e40af; }
  .badge-green { background: #dcfce7; color: #166534; }
</style>

<div class='cs-header'>
  <div>
    <div class='cs-title'>Cost Sheet</div>
    <div class='cs-meta'>{{ doc.name }} &nbsp;|&nbsp; {{ frappe.format(doc.creation, 'Date') }}</div>
  </div>
  <div style='text-align:right'>
    <div style='font-size:13px;font-weight:700;color:#1a3a5c'>{{ doc.customer_name or '' }}</div>
    {% if doc.inquiry %}
    <div class='cs-meta'>Inquiry: {{ doc.inquiry }}</div>
    {% endif %}
  </div>
</div>

<div class='cs-info-grid'>
  <div>
    <div class='lbl'>Subject / Product</div>
    <div class='val'>{{ doc.subject or '—' }}</div>
  </div>
  <div>
    <div class='lbl'>Item Group</div>
    <div class='val'>{{ doc.item_group or '—' }}</div>
  </div>
  <div>
    <div class='lbl'>Colours</div>
    <div class='val'>{{ doc.colour or 0 }}</div>
  </div>
  <div>
    <div class='lbl'>TIEP Status</div>
    <div class='val'>{{ doc.tiep or '—' }}</div>
  </div>
  {% if doc.sales_person %}
  <div>
    <div class='lbl'>Sales Person</div>
    <div class='val'>{{ doc.sales_person }}</div>
  </div>
  {% endif %}
</div>

<table class='pricing'>
  <thead>
    <tr>
      <th>Group</th>
      <th>Item Name</th>
      <th class='r'>Qty</th>
      <th class='r'>Unit Cost (LKR)</th>
      <th class='r'>Cost Amount (LKR)</th>
      <th class='r'>Selling Price (LKR)</th>
      <th class='r'>Selling Amount (LKR)</th>
    </tr>
  </thead>
  <tbody>
    {% for row in rows %}
    <tr>
      <td>{{ row.group_name or '' }}</td>
      <td><b>{{ row.item_name or '' }}</b></td>
      <td class='r'>{{ '{:,.0f}'.format(row.qty or 0) }}</td>
      <td class='r'>{{ '{:,.2f}'.format(row.unit_price or 0) }}</td>
      <td class='r'>{{ '{:,.2f}'.format(row.ammount or 0) }}</td>
      <td class='r'>{{ '{:,.2f}'.format(row.selling_unit_price or 0) }}</td>
      <td class='r'>{{ '{:,.2f}'.format(row.selling_ammount or 0) }}</td>
    </tr>
    {% endfor %}
  </tbody>
  <tfoot>
    <tr>
      <td colspan='4' style='text-align:right;letter-spacing:.03em'>TOTAL</td>
      <td class='r'>{{ '{:,.2f}'.format(total_cost) }}</td>
      <td></td>
      <td class='r'>{{ '{:,.2f}'.format(total_sell) }}</td>
    </tr>
  </tfoot>
</table>

<div class='cs-footer'>
  Generated from Savinda Pricing Calculator &nbsp;&bull;&nbsp; {{ doc.name }}
  &nbsp;&bull;&nbsp; Status: <b>Submitted</b>
</div>
